window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d43973a2e2e5ecb2"]={"versions": [{"id": "FIG-d43973a2e2e5ecb2", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Struktur des AUTOSAR System Templates (Paket FIBEX bzw. Fibex4Lin). Es modelliert die Struktur und Spezialisierung von Substitutions-Frames für linienbasierte Kommunikationssysteme (LIN) im Kontext der CoreCommunication-Infrastruktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>CoreCommunication::Frame</code></strong>: Abstrakte bzw. übergeordnete Basisklasse (gekennzeichnet mit <code>FibexElement</code>), besitzt das Attribut <code>+ frameLength: Int</code>.</li>\n<li><strong><code>SubstitutionFrame</code></strong>: Spezialisierte Klasse mit den Stereotypen <code>«atpType,atpStructureElement»</code>. Sie erbt via Generalisierung von <code>CoreCommunication::Frame</code>. Sie definiert das Attribut <code>+ substitutionType: SubstitutionType</code> sowie eine gerichtete Assoziationsbeziehung <code>+substitutedFrame</code> mit Multiplizität <code>1..*</code> und Eigenschaft <code>{ordered}</code> zurück auf <code>Frame</code>.</li>\n<li><strong><code>SubstitutionType</code></strong>: Aufzählungstyp (<code>«enumeration»</code>) mit den Enumerationswerten <code>sporadic</code> und <code>eventTriggered</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktions- oder Sequenzabläufe. Die Multiplizität <code>1..*</code> mit <code>{ordered}</code> drückt aus, dass ein <code>SubstitutionFrame</code> zur Laufzeit bzw. Konfigurationszeit mindestens einen oder mehrere referenzierte Einzelframes in definierter Reihenfolge substituiert (abhängig vom konfigurierten <code>substitutionType</code>: sporadisch oder ereignisgesteuert).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für das Metamodell des LIN-Substitutionsmechanismus in AUTOSAR:</p>\n<ul class=\"fig-list\">\n<li><code>SubstitutionFrame</code> fungiert selbst als <code>Frame</code>, enthält jedoch eine geordnete Liste ersetzter Frames (<code>substitutedFrame</code>).</li>\n<li>Konfigurationswerkzeuge müssen sicherstellen, dass die Liste <code>substitutedFrame</code> mindestens ein Element umfasst (<code>1..*</code>) und die Reihenfolge (<code>{ordered}</code>) beibehalten wird.</li>\n<li>Das Attribut <code>substitutionType</code> muss zwingend mit einem Literal der Enumeration <code>SubstitutionType</code> (<code>sporadic</code> oder <code>eventTriggered</code>) belegt werden.</li>\n<li>Die Framelänge wird generisch über <code>frameLength</code> vom Basistyp <code>Int</code> vorgegeben.</li>\n</ul>"}, {"id": "FIG-5527bb1ff3974dd7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Struktur des AUTOSAR System Templates (Paket FIBEX bzw. Fibex4Lin). Es modelliert die Struktur und Spezialisierung von Substitutions-Frames für linienbasierte Kommunikationssysteme (LIN) im Kontext der CoreCommunication-Infrastruktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>CoreCommunication::Frame</code></strong>: Abstrakte bzw. übergeordnete Basisklasse (gekennzeichnet mit <code>FibexElement</code>), besitzt das Attribut <code>+ frameLength :Integer</code>.</li>\n<li><strong><code>SubstitutionFrame</code></strong>: Spezialisierte Klasse mit den Stereotypen <code>«atpStructureElement,atpType»</code>. Sie erbt via Generalisierung von <code>CoreCommunication::Frame</code>. Sie definiert das Attribut <code>+ substitutionType :SubstitutionType</code> sowie eine gerichtete Assoziationsbeziehung <code>+substitutedFrame</code> mit Multiplizität <code>1..*</code> und Eigenschaft <code>{ordered}</code> zurück auf <code>Frame</code>.</li>\n<li><strong><code>SubstitutionType</code></strong>: Aufzählungstyp (<code>«enumeration»</code>) mit den Enumerationswerten <code>sporadic</code> und <code>eventTriggered</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktions- oder Sequenzabläufe. Die Multiplizität <code>1..*</code> mit <code>{ordered}</code> drückt aus, dass ein <code>SubstitutionFrame</code> zur Laufzeit bzw. Konfigurationszeit mindestens einen oder mehrere referenzierte Einzelframes in definierter Reihenfolge substituiert (abhängig vom konfigurierten <code>substitutionType</code>: sporadisch oder ereignisgesteuert).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für das Metamodell des LIN-Substitutionsmechanismus in AUTOSAR:</p>\n<ul class=\"fig-list\">\n<li><code>SubstitutionFrame</code> fungiert selbst als <code>Frame</code>, enthält jedoch eine geordnete Liste ersetzter Frames (<code>substitutedFrame</code>).</li>\n<li>Konfigurationswerkzeuge müssen sicherstellen, dass die Liste <code>substitutedFrame</code> mindestens ein Element umfasst (<code>1..*</code>) und die Reihenfolge (<code>{ordered}</code>) beibehalten wird.</li>\n<li>Das Attribut <code>substitutionType</code> muss zwingend mit einem Literal der Enumeration <code>SubstitutionType</code> (<code>sporadic</code> oder <code>eventTriggered</code>) belegt werden.</li>\n<li>Die Framelänge wird generisch über <code>frameLength</code> vom Basistyp <code>Integer</code> vorgegeben.</li>\n</ul>"}], "trans": [{"from": "FIG-d43973a2e2e5ecb2", "to": "FIG-5527bb1ff3974dd7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>CoreCommunication::Frame.frameLength</code>: Datentyp von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li>Stereotypen an <code>SubstitutionFrame</code>: Reihenfolge von <code>«atpType,atpStructureElement»</code> zu <code>«atpStructureElement,atpType»</code> geändert.</li>\n<li>Vererbungskante (<code>SubstitutionFrame</code> zu <code>CoreCommunication::Frame</code>): Linienführung von gerader vertikaler Linie zu rechtwinklig abgeknickter Verbindungslinie angepasst.</li>\n</ul>"}]};
